// ================= LANGUE : version anglaise =================
// Le jeu est écrit en français. En anglais (clé biome_lang = 'en'), on traduit à l'AFFICHAGE seulement :
// - textes de la page (menus, fiches, HUD…) : un MutationObserver traduit les nœuds texte et les attributs title/placeholder/alt ;
// - textes dessinés sur le canvas : fillText/strokeText/measureText sont enveloppés.
// Les données du jeu (FICHES, LEVELS, ids…) ne changent pas : le code continue de comparer des textes français.
// Traduction : 1) phrase exacte (EN_D) ; 2) modèles avec trous {} (EN_T) ; 3) à défaut, remplacement des expressions connues.
// Choix dans Options → Affichage → Langue ; au premier lancement, anglais si le navigateur n'est pas en français.
const LANG=(()=>{let l=null;try{l=localStorage.getItem('biome_lang');if(l&&l[0]==='"')l=JSON.parse(l)}catch(e){}
  if(l==='fr'||l==='en')return l;
  // pas encore choisi : langue du navigateur (les tests automatisés restent en français)
  return navigator.webdriver||/^fr/i.test(navigator.language||'fr')?'fr':'en'})();

